query:
query ($email: String!, $userId: String!, $queryData: AddScheduleMopArgs, $type: String, $selectedLogics: [String!]!, $warehouses: [String!]!, $company: Float!) {
  addScheduleNo(
    selectedLogics: $selectedLogics
    email: $email
    userId: $userId
    type: $type
    queryData: $queryData
    warehouses: $warehouses
    company: $company
  ) {
    status
    description
    __typename
  }
}
